\subsection{Definitions and mathematical statement}
\paragraph{Shared notation.}$\mathbb N$, $\mathbb Z$, $\mathbb Q$, $\mathbb R$, and $\mathbb C$ denote the natural numbers, integers, rationals, reals, and complex numbers, respectively. All additional parameters and hypotheses are specified in the question.


\paragraph{Statement recorded in the supplied source.}
For a very general cubic fourfold $X$, is there a surface $S$ such that the Kuznetsov component $Ku(X) \subset D(X)$ has an embedding $Ku(X) \hookrightarrow D(S)$?
\par\smallskip\textit{Formulation references:} \href{https://huggingface.co/datasets/ulamai/UnsolvedMath}{[S1]}, \href{http://aimpl.org/rationalityag/1/}{[S2]}.

\subsection{Short English statement}
For a very general cubic fourfold $X$, is there a surface $S$ such that the Kuznetsov component $Ku(X) \subset D(X)$ has an embedding $Ku(X) \hookrightarrow D(S)$?

\subsection{Sources}
\begin{itemize}
\item[S1] ULAM.AI and the UnsolvedMath Contributors, UnsolvedMath: A Curated Collection of Open Mathematics Problems, record 20000062 (AIM-ALGEBRAIC\_GEOMETRY-0062). Catalogue attribution under CC BY 4.0.
\url{https://huggingface.co/datasets/ulamai/UnsolvedMath}.
\item[S2] Original problem formulation and mathematical context.
\url{http://aimpl.org/rationalityag/1/}.
\end{itemize}
\label{end:20000062}

